window.__crit={startFollow:startFollow,startTest:startTest,FOLLOW:FOLLOW,TESTS:TESTS,startReview:startReview,updHeader:updHeader,UNITS:UNITS,WIDGETS:WIDGETS,startLesson:startLesson,SIM:SIM,simAdvance:simAdvance,simStart:simStart,simRho:simRho,simTref:simTref,MISSIONS:MISSIONS,S:function(){return S},P:function(){return P},card:function(i){P.i=i;showCard()},renderLearn:renderLearn,curMode:curMode,setLevel:setLevel,curLevel:curLevel,FOLLOW:FOLLOW,closePlayer:closePlayer,showPage:showPage,openUnits:openUnits};
/* 6-mark questions (AQA style), each with the points a mark scheme would look for */
window.SIXQ=[
{id:'p-shc',s:'Physics',short:'Specific heat capacity of a metal block (practical)',q:'Describe a method to find the specific heat capacity of a metal block. You have a 1 kg aluminium block with two holes, an electric heater, a thermometer, a joulemeter and insulation.',
 pts:[{p:'Measure the mass of the block with a balance',k:['mass','balance','weigh']},{p:'Put the heater and the thermometer in the holes (a drop of water or oil helps thermal contact)',k:['heater.{0,40}hole','thermometer.{0,40}hole','in the hole','into the hole']},{p:'Wrap the block in insulation to reduce energy lost to the surroundings',k:['insulat']},{p:'Record the starting temperature',k:['start(ing)? temp','initial temp','temperature at the start','record the temp']},{p:'Switch on and use the joulemeter to measure the energy transferred (or use E = V × I × t)',k:['joulemeter','energy transferred','e ?= ?v','vit']},{p:'Record the temperature rise after a set time, e.g. 10 minutes',k:['10 min','ten min','after.{0,20}min','temperature (rise|change|increase)','final temp']},{p:'Work out c = ΔE ÷ (m × Δθ), or plot temperature against energy and use the gradient',k:['c ?=','δe','divide','gradient','m ?× ?δ','mass.{0,20}temperature change']}],
 model:'Measure the mass of the aluminium block on a balance. Put the heater in one hole and the thermometer in the other, adding a drop of water to the thermometer hole for good thermal contact. Wrap the block in insulation so less energy is lost to the surroundings. Record the starting temperature. Connect the heater through the joulemeter and switch it on. After 10 minutes, record the energy transferred from the joulemeter and the final temperature, and work out the temperature rise. Calculate the specific heat capacity using c = ΔE ÷ (m × Δθ). For a better result, record the temperature every minute, plot temperature against energy and use the gradient.'},
{id:'p-fission',s:'Physics',short:'Chain reactions and control rods',q:'Explain how a chain reaction happens in a nuclear reactor and how the reactor is controlled.',
 pts:[{p:'A neutron is absorbed by a uranium-235 nucleus',k:['absorb.{0,40}(uranium|nucle)','uranium.{0,40}absorb','neutron.{0,30}(hits|collides|enters)']},{p:'The nucleus becomes unstable and splits into two smaller (daughter) nuclei',k:['split','two smaller','daughter','fission']},{p:'Two or three neutrons are released, along with energy',k:['(2|two|3|three).{0,20}neutrons','neutrons.{0,20}released','release.{0,20}energy']},{p:'These neutrons cause more fissions: a chain reaction',k:['chain','more fission','further fission','go on to']},{p:'A moderator (e.g. graphite or water) slows the neutrons so they are more likely to cause fission',k:['moderator','graphite','slows? (down )?(the )?neutrons']},{p:'Control rods (e.g. boron) absorb neutrons',k:['control rod','boron','absorb.{0,20}neutron']},{p:'Lowering the rods absorbs more neutrons and slows the reaction; raising them speeds it up, so on average one neutron per fission causes another',k:['lower','raise','insert','withdraw','one neutron','steady']}],
 model:'A uranium-235 nucleus absorbs a neutron and becomes unstable. It splits into two smaller daughter nuclei and releases two or three neutrons, plus a lot of energy. These neutrons can be absorbed by other uranium-235 nuclei, causing more fissions: a chain reaction. A moderator such as water slows the neutrons down so they are more likely to cause fission. The reaction is controlled with control rods made of boron, which absorb neutrons. Lowering the rods further into the core absorbs more neutrons and slows the reaction; raising them lets it speed up. In normal operation, the rods are set so that on average one neutron from each fission causes one more fission, keeping the reaction steady.'},
{id:'p-wire',s:'Physics',short:'Length and resistance of a wire (practical)',q:'Describe how you could investigate how the length of a wire affects its resistance.',
 pts:[{p:'Set up a circuit with the wire, a battery or power supply and an ammeter in series',k:['series','ammeter']},{p:'Connect a voltmeter in parallel across the length of wire',k:['parallel','voltmeter']},{p:'Use crocodile clips to change the length, measured with a metre ruler',k:['crocodile','clip','metre ruler','ruler']},{p:'Record the current and the potential difference for each length',k:['record','current and','reading']},{p:'Calculate resistance using R = V ÷ I',k:['r ?= ?v','v ?÷ ?i','v/i','divide']},{p:'Keep the current low or switch off between readings so the wire doesn\'t heat up',k:['heat','switch off','low current','temperature']},{p:'Repeat, take a mean, and plot resistance against length',k:['repeat','mean','average','plot','graph']}],
 model:'Tape the wire to a metre ruler and connect it in a circuit with a battery and an ammeter in series. Connect a voltmeter in parallel across the wire. Attach one crocodile clip at 0 cm and move the other to change the length, starting at 10 cm. For each length, record the current and potential difference and calculate the resistance with R = V ÷ I. Increase the length in 10 cm steps up to 100 cm. Switch off between readings so the wire doesn\'t heat up, since heating changes its resistance. Repeat the readings, calculate means and plot a graph of resistance against length.'},
{id:'p-lamp',s:'Physics',short:'I–V characteristic of a filament lamp (practical)',q:'Describe how to find the I–V characteristic of a filament lamp, and explain the shape of the graph you would expect.',
 pts:[{p:'Lamp in series with an ammeter and a variable resistor (or variable power supply)',k:['variable resistor','rheostat','variable power','ammeter']},{p:'Voltmeter in parallel across the lamp',k:['parallel','voltmeter']},{p:'Change the potential difference in steps and record the current each time',k:['record','change the (p\\.?d|potential|voltage)','vary','steps']},{p:'Swap the connections to get negative values too',k:['reverse','swap','negative']},{p:'Plot current against potential difference',k:['plot','graph']},{p:'The graph is a curve, getting less steep as the pd increases',k:['curve','less steep','not straight','levels off']},{p:'The filament heats up, so its resistance increases',k:['heat','hot','temperature','resistance increase']}],
 model:'Connect the lamp in series with an ammeter and a variable resistor, with a voltmeter in parallel across the lamp. Adjust the variable resistor to change the potential difference in steps, recording the current each time. Then swap the battery connections round and repeat to get negative values. Plot current against potential difference. The graph is an S-shaped curve through the origin that gets less steep as the potential difference increases, because the filament gets hotter. As the temperature rises, the metal ions vibrate more, so the resistance increases.'},
{id:'p-energy',s:'Physics',short:'Evaluate nuclear power and wind turbines',q:'Evaluate the use of nuclear power stations and wind turbines for generating the UK\'s electricity.',
 pts:[{p:'Nuclear is reliable: it generates all the time, whatever the weather',k:['reliable','all the time','weather','constant']},{p:'Nuclear gives a huge output from a small mass of fuel and a small site',k:['small (amount|mass)','huge','large (amount|output)','lots of energy']},{p:'Neither releases carbon dioxide while generating',k:['carbon','co2','greenhouse','no emissions']},{p:'Nuclear makes radioactive waste that must be stored safely for a very long time',k:['waste','radioactive']},{p:'Nuclear has high build and decommissioning costs and takes years to build',k:['cost','expensive','decommission','years to build']},{p:'Wind is renewable with no fuel cost, but unreliable because it depends on the wind',k:['renewable','unreliable','depends on.{0,10}wind','not always','intermittent']},{p:'Wind needs many turbines over a large area, which some people think spoil the view',k:['many turbines','large area','spoil','noise','view']},{p:'A conclusion: e.g. use both, nuclear for steady supply and wind to cut emissions',k:['conclusion','overall','both','mix','i think']}],
 model:'Nuclear power stations are reliable: they generate all the time, whatever the weather, and a small mass of fuel produces a huge amount of energy. Like wind turbines, they release no carbon dioxide while generating. However, they produce radioactive waste that has to be stored safely for thousands of years, and they are very expensive and slow to build and decommission. Wind turbines are renewable and have no fuel costs, but their output depends on the wind, so they are unreliable, and you need a lot of turbines over a large area. Overall, the UK is best using both: nuclear for a steady base supply and wind to cut emissions further.'},
{id:'p-stop',s:'Physics',short:'Factors that affect stopping distance',q:'Explain the factors that affect the stopping distance of a car.',
 pts:[{p:'Stopping distance = thinking distance + braking distance',k:['thinking distance','braking distance','\\+']},{p:'Thinking distance depends on the driver\'s reaction time',k:['reaction time']},{p:'Tiredness, alcohol, drugs and distractions increase reaction time',k:['tired','alcohol','drug','distract','phone']},{p:'Higher speed increases both thinking and braking distance',k:['speed']},{p:'Braking distance increases on wet or icy roads (less friction)',k:['wet','ic(e|y)','friction','road condition']},{p:'Worn tyres or brakes, or a heavier car, increase braking distance',k:['tyre','brakes','mass','heav']},{p:'Kinetic energy depends on speed squared, so braking distance rises sharply with speed',k:['kinetic','squared','v²','v2']}],
 model:'Stopping distance is the thinking distance plus the braking distance. Thinking distance depends on how fast you are going and on the driver\'s reaction time, which is longer if they are tired, have drunk alcohol or taken drugs, or are distracted by a phone. Braking distance depends on speed too, and also on friction between the tyres and the road: wet or icy roads and worn tyres or brakes make it longer. A heavier car also takes longer to stop. Because kinetic energy depends on speed squared, doubling the speed makes the braking distance about four times longer.'},
{id:'p-spring',s:'Physics',short:'Force and extension of a spring (practical)',q:'Describe how to investigate the relationship between force and extension for a spring.',
 pts:[{p:'Hang the spring from a clamp stand with a vertical ruler beside it',k:['clamp','stand','ruler']},{p:'Measure the original (unstretched) length, using a pointer to read the ruler at eye level',k:['original length','unstretched','pointer','eye level']},{p:'Add masses one at a time (e.g. 100 g, which is about 1 N)',k:['add.{0,20}mass','masses','100 ?g','weights','one at a time']},{p:'Measure the new length each time and work out the extension',k:['extension','new length']},{p:'Calculate the force (weight) using W = m × g',k:['w ?= ?m','weight','mg','newton']},{p:'Plot force against extension',k:['plot','graph']},{p:'A straight line through the origin shows they are proportional, up to the limit of proportionality',k:['straight line','proportional','origin','limit']}],
 model:'Hang the spring from a clamp stand and fix a metre ruler vertically beside it. Attach a pointer to the bottom of the spring and read its position at eye level to get the original length. Add a 100 g mass (a force of about 1 N) and measure the new length. The extension is the new length minus the original length. Keep adding masses one at a time, recording the length each time, and calculate each force using W = m × g. Plot force against extension. A straight line through the origin shows that extension is proportional to force, until the spring passes its limit of proportionality.'},
{id:'p-grid',s:'Physics',short:'Why the National Grid uses transformers',q:'Explain why the National Grid uses step-up and step-down transformers.',
 pts:[{p:'Step-up transformers at power stations increase the potential difference (to hundreds of thousands of volts)',k:['step.?up','increase.{0,20}(pd|potential|voltage)','400','high voltage']},{p:'For the same power, a higher pd means a lower current',k:['lower current','current.{0,20}(lower|decrease|reduce)','less current']},{p:'A lower current means less heating in the cables',k:['heat','p ?= ?i','i²r','i2r']},{p:'So less energy is wasted, which makes the system more efficient',k:['efficien','less energy (is )?(lost|wasted)','energy loss']},{p:'Step-down transformers reduce the pd to 230 V for homes',k:['step.?down','230','reduce.{0,20}(pd|potential|voltage)']},{p:'A lower pd is safer to use in homes',k:['safe']}],
 model:'Power stations generate electricity, and step-up transformers increase the potential difference to around 400,000 V. For the same power, a higher potential difference means a much lower current. A lower current causes less heating in the cables (P = I²R), so less energy is wasted and the grid is more efficient. Near homes, step-down transformers reduce the potential difference to 230 V, which is much safer to use in homes.'},
{id:'c-salt',s:'Chemistry',short:'Pure, dry copper sulfate crystals (practical)',q:'Describe how to make pure, dry crystals of copper sulfate from copper oxide and dilute sulfuric acid.',
 pts:[{p:'Warm the dilute sulfuric acid',k:['warm','heat the acid','gently heat']},{p:'Add copper oxide a little at a time, stirring',k:['add.{0,20}copper oxide','stir','a little at a time','spatula']},{p:'Keep adding until it is in excess (no more dissolves)',k:['excess','no more dissolves','stops dissolving']},{p:'Filter to remove the excess copper oxide',k:['filter']},{p:'Heat the solution in an evaporating basin to crystallisation point (evaporate some of the water)',k:['evaporat','crystallisation point','heat the solution']},{p:'Leave it to cool so crystals form',k:['cool','crystals form','leave']},{p:'Pat the crystals dry with filter paper or leave them somewhere warm',k:['dry','filter paper','pat']}],
 model:'Gently warm some dilute sulfuric acid in a beaker. Add copper oxide a spatula at a time, stirring, until no more dissolves, so the copper oxide is in excess and all the acid has reacted. Filter the mixture to remove the excess copper oxide. Pour the blue filtrate into an evaporating basin and heat it gently to evaporate some of the water, until it reaches its crystallisation point. Leave it to cool so that crystals form. Remove the crystals and pat them dry with filter paper.'},
{id:'c-brine',s:'Chemistry',short:'Electrolysis of sodium chloride solution',q:'Explain what happens during the electrolysis of sodium chloride solution (brine), including the products at each electrode.',
 pts:[{p:'The solution contains Na⁺, Cl⁻, H⁺ and OH⁻ ions (from the water)',k:['na\\+','cl-','h\\+','oh-','ions','from the water']},{p:'At the cathode (negative), hydrogen gas forms',k:['hydrogen','cathode']},{p:'Hydrogen forms instead of sodium because sodium is more reactive than hydrogen',k:['more reactive','reactiv']},{p:'At the anode (positive), chlorine gas forms',k:['chlorine','anode']},{p:'Chloride ions lose electrons (oxidation); hydrogen ions gain electrons (reduction)',k:['lose electron','gain electron','oxidis','reduc']},{p:'Sodium hydroxide solution is left behind',k:['sodium hydroxide']},{p:'Tests: hydrogen gives a squeaky pop; chlorine bleaches damp litmus paper',k:['squeaky','pop','bleach','litmus']}],
 model:'Brine contains sodium ions and chloride ions, plus hydrogen ions and hydroxide ions from the water. At the negative cathode, hydrogen gas is produced rather than sodium, because sodium is more reactive than hydrogen: hydrogen ions gain electrons (reduction). At the positive anode, chloride ions lose electrons (oxidation) to form chlorine gas. The sodium ions and hydroxide ions stay in solution, so sodium hydroxide solution is left. Hydrogen gives a squeaky pop with a lit splint, and chlorine bleaches damp litmus paper.'},
{id:'c-rate',s:'Chemistry',short:'Concentration and rate: the disappearing cross (practical)',q:'Describe how to investigate the effect of concentration on the rate of the reaction between sodium thiosulfate and hydrochloric acid.',
 pts:[{p:'Measure a set volume of sodium thiosulfate solution into a conical flask',k:['measur','volume','conical flask','measuring cylinder']},{p:'Put the flask on a piece of paper with a black cross drawn on it',k:['cross','paper']},{p:'Add the hydrochloric acid and start the timer',k:['add.{0,30}acid','start.{0,20}(timer|stopwatch|clock)']},{p:'Time how long it takes for the cross to disappear (a sulfur precipitate forms)',k:['disappear','precipitate','sulfur','cloudy']},{p:'Repeat with different concentrations by diluting the thiosulfate with water, keeping the total volume the same',k:['different concentration','dilut','water','total volume']},{p:'Keep the acid volume, concentration and temperature the same',k:['same temperature','control','keep.{0,30}same','temperature']},{p:'Repeat and take a mean; rate is proportional to 1 ÷ time',k:['repeat','mean','1 ?÷ ?time','1/t','rate ?=']}],
 model:'Measure 50 cm³ of sodium thiosulfate solution into a conical flask and put the flask on a piece of paper marked with a black cross. Add 5 cm³ of dilute hydrochloric acid, swirl, and start a stopwatch. Looking down through the flask, time how long it takes for the cross to disappear as the sulfur precipitate makes the solution cloudy. Repeat with different concentrations of thiosulfate, made by mixing it with water while keeping the total volume at 50 cm³. Keep the acid volume and concentration and the temperature the same. Repeat each concentration, take a mean, and work out the rate as 1 ÷ time.'},
{id:'c-titr',s:'Chemistry',short:'Titration (practical)',q:'Describe how to carry out a titration to find the volume of acid needed to neutralise 25.0 cm³ of sodium hydroxide solution.',
 pts:[{p:'Use a pipette to measure 25.0 cm³ of sodium hydroxide into a conical flask',k:['pipette','25']},{p:'Add a few drops of indicator (e.g. phenolphthalein or methyl orange)',k:['indicator','phenolphthalein','methyl orange']},{p:'Fill the burette with acid and record the starting reading',k:['burette','start(ing)? reading','initial reading']},{p:'Add the acid while swirling the flask',k:['swirl']},{p:'Add it drop by drop near the end point',k:['drop','dropwise','end point','endpoint']},{p:'Stop when the indicator changes colour and record the volume used',k:['colour change','changes colour','record.{0,20}volume','final reading']},{p:'Repeat until you get concordant results (within 0.10 cm³) and work out the mean',k:['concordant','repeat','mean','0\\.1']}],
 model:'Use a pipette and pipette filler to measure 25.0 cm³ of sodium hydroxide solution into a conical flask, and add a few drops of phenolphthalein indicator. Fill a burette with the acid and record the starting volume, reading the bottom of the meniscus at eye level. Add the acid to the flask while swirling. As you get close to the end point, add it drop by drop. Stop as soon as the indicator changes colour and record the final volume. Repeat the titration until you have concordant results, within 0.10 cm³ of each other, and calculate the mean.'},
{id:'c-chrom',s:'Chemistry',short:'Paper chromatography (practical)',q:'Describe how to use paper chromatography to identify the colours in an ink, including how to calculate Rf values.',
 pts:[{p:'Draw a start line in pencil near the bottom of the paper (pencil won\'t dissolve)',k:['pencil']},{p:'Put a small spot of the ink (and known dyes) on the line',k:['spot','dot']},{p:'Stand the paper in a solvent with the solvent below the start line',k:['solvent','below the line','beaker']},{p:'Wait for the solvent to move up the paper, then mark the solvent front',k:['solvent front','move up','rise']},{p:'Rf = distance moved by the spot ÷ distance moved by the solvent',k:['rf','distance moved','÷','divide']},{p:'Compare the Rf values or spots with known substances to identify them',k:['compare','known','reference','match']}],
 model:'Draw a start line in pencil about 2 cm from the bottom of the chromatography paper, using pencil because it won\'t dissolve in the solvent. Put a small spot of the ink on the line, with spots of known dyes beside it. Stand the paper in a beaker of solvent so the solvent is below the line, and put a lid on. When the solvent has nearly reached the top, take the paper out and mark the solvent front in pencil, then let it dry. Measure how far each spot and the solvent moved, and calculate Rf = distance moved by the spot ÷ distance moved by the solvent. Compare the spots and Rf values with the known dyes to identify the colours in the ink.'},
{id:'c-metal',s:'Chemistry',short:'How metals are extracted from their ores',q:'Explain how the method used to extract a metal from its ore depends on the metal\'s reactivity.',
 pts:[{p:'Very unreactive metals such as gold are found as the metal itself',k:['gold','unreactive','native','found as']},{p:'Metals less reactive than carbon can be extracted by reduction with carbon',k:['less reactive than carbon','reduc','carbon']},{p:'Example: iron oxide is heated with carbon to give iron and carbon dioxide',k:['iron','blast furnace','carbon dioxide']},{p:'Reduction means losing oxygen',k:['loss of oxygen','loses oxygen','removes oxygen','remove the oxygen']},{p:'Metals more reactive than carbon, such as aluminium, are extracted by electrolysis',k:['electrolysis','aluminium','more reactive than carbon']},{p:'Electrolysis needs lots of energy (electricity and high temperatures), so it is expensive',k:['expensive','energy','electricity','cost']}],
 model:'The method depends on where the metal is in the reactivity series compared with carbon. Very unreactive metals such as gold are found as the metal itself. Metals less reactive than carbon, such as iron, are extracted by reduction with carbon: iron oxide is heated with carbon, which removes the oxygen to give iron and carbon dioxide. Reduction is the loss of oxygen. Metals more reactive than carbon, such as aluminium, can\'t be reduced by carbon, so they are extracted by electrolysis of the molten compound. Electrolysis uses a lot of electricity and high temperatures, so it is expensive.'},
{id:'c-crude',s:'Chemistry',short:'Fractional distillation of crude oil',q:'Describe and explain how crude oil is separated into fractions by fractional distillation.',
 pts:[{p:'Crude oil is heated until most of it evaporates (vaporises)',k:['heat','evaporat','vapor','vapour','gas']},{p:'The vapour goes into a fractionating column',k:['column']},{p:'The column is hot at the bottom and cooler at the top',k:['hot.{0,20}bottom','cool.{0,20}top','temperature gradient']},{p:'The vapours rise and condense when they reach a level below their boiling point',k:['condense','boiling point']},{p:'Long-chain hydrocarbons have high boiling points and are collected near the bottom',k:['long.?chain','bottom','high boiling']},{p:'Short-chain hydrocarbons have low boiling points and rise higher up the column',k:['short.?chain','top','low boiling','higher up']},{p:'Each fraction contains hydrocarbons with similar chain lengths and boiling points',k:['similar','fraction']}],
 model:'Crude oil is heated until most of it evaporates, and the vapour is fed into the bottom of a fractionating column. The column is hot at the bottom and gets cooler towards the top. As the vapours rise, each hydrocarbon condenses when it reaches a level that is cooler than its boiling point. Long-chain hydrocarbons have high boiling points, so they condense and are collected near the bottom, as bitumen and heavy fuel oil. Short-chain hydrocarbons have low boiling points, so they rise higher before condensing, giving fractions like petrol and gases at the top. Each fraction contains hydrocarbons with similar chain lengths and boiling points.'},
{id:'c-water',s:'Chemistry',short:'Potable water from fresh water and sea water',q:'Describe how potable water is produced in the UK, and explain how sea water can be made drinkable.',
 pts:[{p:'Choose a source of fresh water: lakes, rivers, reservoirs or groundwater',k:['lake','river','reservoir','ground ?water','rain']},{p:'Pass it through filter beds to remove solid particles',k:['filter']},{p:'Sterilise it to kill microbes, using chlorine, ozone or ultraviolet light',k:['steril','chlorine','ozone','uv','ultraviolet','microb','bacteria']},{p:'Potable water is safe to drink but is not pure: it still has dissolved substances',k:['not pure','dissolved','safe to drink']},{p:'Sea water can be desalinated by distillation (boil it and condense the steam)',k:['distil','desalinat','boil','condense']},{p:'Or by reverse osmosis, pushing it through a membrane',k:['reverse osmosis','membrane']},{p:'Desalination needs lots of energy, so it is expensive',k:['energy','expensive','cost']}],
 model:'In the UK, potable water usually comes from fresh water such as rain collected in reservoirs, rivers and lakes, or groundwater. It is passed through filter beds to remove solid particles, then sterilised to kill harmful microbes using chlorine, ozone or ultraviolet light. Potable water is safe to drink, but it isn\'t pure: it still contains dissolved substances. Sea water has too much dissolved salt to drink, so it has to be desalinated, either by distillation, where it is boiled and the steam condensed, or by reverse osmosis, where it is forced through a membrane. Both need a lot of energy, so desalination is expensive and only used where fresh water is scarce.'}];
